import React from "react";
import { flexRender } from "@tanstack/react-table";
import { clsx } from "clsx";
import { ArrowDown, ArrowUp, VerticalScroll } from "@exp-textura/icons";

import { useTable } from "../hooks/use-table";
import { useTableKeyboardNavContext } from "../hooks/use-table-keyboard-nav-context";
import { TableClasses } from "../table.styles";

export const TableHeader = (props: React.HTMLAttributes<HTMLTableSectionElement>) => {
  const table = useTable();
  const { enableKeyboardShortcuts, handleKeyDown } = useTableKeyboardNavContext();

  return (
    <thead {...props} className={clsx(TableClasses.header, props.className)}>
      {table.getHeaderGroups().map((headerGroup, rowIndex) => (
        <tr key={headerGroup.id} className={TableClasses.headerRow}>
          {headerGroup.headers.map((header, colIndex) => {
            const headerContent = flexRender(header.column.columnDef.header, header.getContext());
            return (
              <th
                key={header.id}
                aria-sort={
                  header.column.getIsSorted()
                    ? header.column.getIsSorted() === "asc"
                      ? "ascending"
                      : "descending"
                    : "none"
                }
                className={TableClasses.headerCell}
                colSpan={header.colSpan}
                data-col={table.options.enableRowSelection ? colIndex + 1 : colIndex}
                data-column-id={header.id}
                data-row={rowIndex}
                id={header.id}
                style={{
                  // Skip TanStack's defaultColumnSizing (150/20/MAX) — see table-body.tsx.
                  width: header.column.columnDef.size !== 150 ? header.getSize() : undefined,
                  minWidth:
                    header.column.columnDef.minSize !== 20
                      ? header.column.columnDef.minSize
                      : undefined,
                  maxWidth:
                    header.column.columnDef.maxSize !== Number.MAX_SAFE_INTEGER
                      ? header.column.columnDef.maxSize
                      : undefined,
                  cursor: header.column.getCanSort() ? "pointer" : "default",
                  visibility:
                    typeof headerContent === "string" || header.id === "select"
                      ? "visible"
                      : "hidden",
                }}
                tabIndex={enableKeyboardShortcuts ? 0 : -1}
                onClick={header.column.getToggleSortingHandler()}
                onKeyDown={(e) => {
                  if (enableKeyboardShortcuts) {
                    handleKeyDown?.(e);
                    if (e.key === "Enter" || e.key === " ") {
                      header.column.getToggleSortingHandler()?.(e);
                    }
                  }
                }}
              >
                <div
                  className={TableClasses.headerCellContent}
                  data-sort={header.column.getIsSorted()}
                >
                  {headerContent}
                  {header.column.getCanSort() &&
                    ({
                      asc: <ArrowUp name="arrow-up" />,
                      desc: <ArrowDown name="arrow-down" />,
                    }[header.column.getIsSorted() as string] ?? <VerticalScroll />)}
                </div>
              </th>
            );
          })}
        </tr>
      ))}
    </thead>
  );
};

TableHeader.displayName = "Table.Header";
